import { readdirSync, readFileSync, statSync } from "node:fs";
import path from "node:path";

import { describe, expect, it } from "vitest";

/**
 * One icon module (components/icons; docs/ui/UI-03-nesto-theme.md §6): every
 * icon is an IBM Carbon glyph, generated by scripts/icons/generate.mjs. No icon
 * package is imported at runtime, so no other drawing can slip in.
 */

const ROOT = process.cwd();

function files(dir: string): string[] {
  const out: string[] = [];
  for (const entry of readdirSync(dir)) {
    const file = path.join(dir, entry);
    if (statSync(file).isDirectory()) out.push(...files(file));
    else if (/\.(ts|tsx)$/.test(entry)) out.push(file);
  }
  return out;
}

describe("icons", () => {
  it("nothing imports an icon package; icons come from @/components/icons", () => {
    const offenders = ["app", "components", "lib"]
      .flatMap((dir) => files(path.join(ROOT, dir)))
      .map((file) => path.relative(ROOT, file).split(path.sep).join("/"))
      .filter((file) => /from\s+["'](lucide-react|@carbon\/icons[^"']*)["']/.test(readFileSync(path.join(ROOT, file), "utf8")));
    expect(offenders).toEqual([]);
  });

  it("every icon in the module has a Carbon glyph", () => {
    const index = readFileSync(path.join(ROOT, "components/icons/index.ts"), "utf8");
    const icons = [...index.matchAll(/^export const (\w+) = \/\* @__PURE__ \*\/ glyph\("\1", "(.*)"\);$/gm)];
    expect(icons.length).toBeGreaterThan(250);
    for (const [, name, markup] of icons) expect(markup.length, name).toBeGreaterThan(20);
  });
});
